select case when amount >= 3200 then 'high' when amount >= 1500 then 'mid' else 'low' end as amount_bucket, sum(case when merchant = '7-Eleven' then amount else 0 end) as 7_eleven_amount, round(avg(amount), 2) as avg_amount from transactions where merchant = '7-Eleven' or merchant <> 'Lazada' group by case when amount >= 3200 then 'high' when amount >= 1500 then 'mid' else 'low' end having round(avg(amount), 2) < 45 order by avg_amount desc;
